GPU_MEM_SIZE = 80 # GB

# EVOLVE-BLOCK-START

def compute_model_placement(gpu_num, models):
    """
    Greedy placement followed by local-search refinement (moves and swaps)
    that repeatedly reduces the maximum KVPR across GPUs.
    """
    if not models:
        return {gpu_id: [] for gpu_id in range(gpu_num)}

    def kvprs(load, free):
        return [load[i] / free[i] if free[i] > 0 else float('inf') for i in range(len(load))]

    def greedy(order):
        placement = {g: [] for g in range(gpu_num)}
        free = [GPU_MEM_SIZE] * gpu_num
        load = [0.0] * gpu_num
        for model in order:
            best, best_r = None, float('inf')
            for g in range(gpu_num):
                if model.model_size <= free[g]:
                    r = load[g] / free[g]
                    if r < best_r:
                        best_r, best = r, g
            if best is None:
                return None, None, None
            placement[best].append(model)
            load[best] += model.req_rate / model.slo
            free[best] -= model.model_size
        return placement, load, free

    # Lower-bound-guided construction: target the analytic LP bound
    # L = (sum req_rate/slo) / (gpus * MEM - sum sizes), assigning each model
    # to the GPU whose post-placement KVPR lands closest to L (equalizing
    # per-GPU pressure toward the analytic optimum) instead of greedily
    # minimizing each step. Falls back to incumbent greedy when infeasible.
    total_load = sum(m.req_rate / m.slo for m in models)
    total_free = gpu_num * GPU_MEM_SIZE - sum(m.model_size for m in models)
    L = total_load / total_free if total_free > 0 else float('inf')

    def target_greedy(order):
        placement = {g: [] for g in range(gpu_num)}
        free = [float(GPU_MEM_SIZE)] * gpu_num
        load = [0.0] * gpu_num
        for model in order:
            w = model.req_rate / model.slo
            best, best_key = None, None
            for g in range(gpu_num):
                denom = free[g] - model.model_size
                if denom <= 1e-12:
                    continue
                post = (load[g] + w) / denom
                # Prefer landing at or below the LP bound L; penalize overshoot.
                key = (post > L, abs(post - L), -free[g])
                if best_key is None or key < best_key:
                    best_key, best = key, g
            if best is None:
                return None, None, None
            placement[best].append(model)
            load[best] += w
            free[best] -= model.model_size
        return placement, load, free

    # Try target-greedy for a few orderings, keeping the best of
    # target-greedy AND plain greedy per ordering (target-greedy equalizes
    # toward the LP bound, but plain greedy can win on tight instances).
    best = None
    for order in (
        sorted(models, key=lambda m: m.req_rate / m.slo, reverse=True),
        sorted(models, key=lambda m: m.model_size, reverse=True),
        sorted(models, key=lambda m: m.req_rate / m.slo / m.model_size, reverse=True),
    ):
        for p, l, f in (target_greedy(order), greedy(order)):
            if p is not None and (best is None or max(kvprs(l, f)) < best[1]):
                best = (p, max(kvprs(l, f)), l, f)
    if best is None:
        raise ValueError("Unable to place models on any GPU within memory limits.")
    placement, cur_max, load, free = best

    # LP-relaxation seed + SA polish. For a fixed pressure bound t the
    # fractional min-max-ratio relaxation is a linear program: variables
    # x[i,g] in [0,1], sum_g x[i,g]=1, memory limits per GPU, and the ratio
    # constraint rearranged to sum_i (w_i + t*size_i) x[i,g] <= t*MEM.
    # Bisection on t yields the fractional optimum (a lower bound greedy
    # never reaches); rounding it plus memory repair gives an extra SA seed.
    import numpy as np
    from scipy.optimize import linprog
    rng = np.random.default_rng(0)
    sizes = [m.model_size for m in models]
    weights = [m.req_rate / m.slo for m in models]
    n = len(models)
    G = gpu_num

    def objective(assign):
        lo = [0.0] * G
        used = [0.0] * G
        for i, g in enumerate(assign):
            lo[g] += weights[i]
            used[g] += sizes[i]
        return max(lo[g] / (GPU_MEM_SIZE - used[g]) if used[g] < GPU_MEM_SIZE else float('inf')
                   for g in range(G))

    x = [0] * n
    for g in range(gpu_num):
        for m in placement[g]:
            x[models.index(m)] = g

    def lp_round():
        """Solve fractional LP by bisection on t, round largest-share, repair memory."""
        def lp_feasible(t):
            A_eq = np.zeros((n, n * G))
            b_eq = np.ones(n)
            for i in range(n):
                A_eq[i, i * G:(i + 1) * G] = 1.0
            A_ub = np.zeros((G, n * G))
            b_ub = np.full(G, t * GPU_MEM_SIZE)
            for g in range(G):
                for i in range(n):
                    A_ub[g, i * G + g] = weights[i] + t * sizes[i]
            res = linprog(np.zeros(n * G), A_ub=A_ub, b_ub=b_ub,
                          A_eq=A_eq, b_eq=b_eq, bounds=(0.0, 1.0), method='highs')
            return np.asarray(res.x, dtype=float).reshape(n, G) if res.success else None

        hi, lo, X = max(cur_max, 1e-9), 0.0, None
        for _ in range(35):
            mid = 0.5 * (lo + hi)
            s = lp_feasible(mid)
            if s is None:
                lo = mid
            else:
                X, hi = s, mid
            if hi - lo < 1e-9:
                break
        if X is None:
            return None
        xr = [int(np.argmax(X[i])) for i in range(n)]
        for _ in range(5 * n + 10):
            used = [0.0] * G
            for i, g in enumerate(xr):
                used[g] += sizes[i]
            over = [g for g in range(G) if used[g] > GPU_MEM_SIZE]
            if not over:
                break
            g = over[0]
            src = [i for i in range(n) if xr[i] == g]
            if not src:
                return None
            i = min(src, key=lambda k: weights[k])
            bb, bv = None, float('inf')
            for b in range(G):
                if b == g or used[b] + sizes[i] > GPU_MEM_SIZE:
                    continue
                c = xr[:]
                c[i] = b
                v = objective(c)
                if v < bv:
                    bv, bb = v, b
            if bb is None:
                return None
            xr[i] = bb
        used = [0.0] * G
        for i, g in enumerate(xr):
            used[g] += sizes[i]
        if any(u > GPU_MEM_SIZE for u in used):
            return None
        return xr

    seeds = [x[:]]
    lp_x = lp_round()
    if lp_x is not None:
        seeds.append(lp_x)

    best_x, best = x[:], objective(x)
    T0 = max(best / 10.0, 1e-3)
    iters = 12000
    for seed in seeds:
        x, cur = seed[:], objective(seed)
        if cur < best:
            best_x, best = x[:], cur
        for it in range(iters):
            T = T0 * (1e-4 / T0) ** (it / iters)
            cand = x[:]
            i = int(rng.integers(n))
            if rng.random() < 0.5:
                cand[i] = int(rng.integers(G))
            else:
                j = int(rng.integers(n))
                cand[i], cand[j] = cand[j], cand[i]
            used = [0.0] * G
            for k, g in enumerate(cand):
                used[g] += sizes[k]
            if any(u > GPU_MEM_SIZE for u in used):
                continue
            cv = objective(cand)
            if cv < cur or rng.random() < np.exp((cur - cv) / max(T, 1e-12)):
                x, cur = cand, cv
                if cur < best:
                    best_x, best = x[:], cur

    placement = {g: [] for g in range(gpu_num)}
    for i, g in enumerate(best_x):
        placement[g].append(models[i])
    return placement

# EVOLVE-BLOCK-END


if __name__ == "__main__":
    # Test the algorithm

    from evaluator import generate_test_gpu_models
    from evaluator import calculate_kvcache_pressure
    from evaluator import safe_float
    import numpy as np

    test_cases = generate_test_gpu_models()
    all_kvpr = []
    for i, (gpu_num, gpu_models) in enumerate(test_cases):

        results = compute_model_placement(gpu_num, gpu_models)
        max_kvpr = calculate_kvcache_pressure(results)
        all_kvpr.append(safe_float(max_kvpr))

    avg_kvpr = np.mean(all_kvpr)
    if avg_kvpr != 0:
        avg_kvpr = 1.0 / avg_kvpr


    print(f"Max KVPR: {avg_kvpr:.3f}")

